#include "stdlib/stats/base/dists/burr-type3/cdf.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/math/base/assert/is_nan.h"

/**
* Evaluates the cumulative distribution function (CDF) for a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d` at a value `x`.
*
* @param x    input value
* @param c    first shape parameter
* @param d    second shape parameter
* @return     evaluated CDF
*
* @example
* double y = stdlib_base_dists_burr_type3_cdf( 0.1, 1.0, 1.0 );
* // returns ~0.091
*/
double stdlib_base_dists_burr_type3_cdf( const double x, const double c, const double d ) {
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( c ) ||
		stdlib_base_is_nan( d ) ||
		c <= 0.0 ||
		d <= 0.0 ||
		x <= 0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	return stdlib_base_pow( 1.0 + stdlib_base_pow( x, -c ), -d );
}
